def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    out_rows = rows * rows
    out_cols = cols * cols

    output = [[0] * out_cols for _ in range(out_rows)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != 0:
                # Place a copy of the grid in block (i, j)
                for r in range(rows):
                    for c in range(cols):
                        output[i * rows + r][j * cols + c] = grid[r][c]

    return output
